package com.farika.soundflow;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.webkit.*;import org.json.*;import java.util.*;
/** Background first-party request transport. Never navigates the app or completes a challenge invisibly. */
public class AccountWriter {
 public interface Callback {void complete(Intent result);void failed(int status,String reason,boolean verification);}
 protected final Activity activity;protected final Context context;private final Callback callback;private final Handler handler=new Handler(Looper.getMainLooper());
 private static final java.util.concurrent.atomic.AtomicReference<AccountWriter> writing=new java.util.concurrent.atomic.AtomicReference<>();
 private void releaseWrite(){writing.compareAndSet(this,null);}
 private WebView web;private boolean busy,ready,current,executing,closed;private String client="",observed="",owner="",op="",track="",playlist="",title="",key="",authUsed="",clientUsed="";private String browserOwner="";private long browserEpoch;private long deadline;private String pageHost="not_loaded";private int pageError=0,pageHttp=0,apiRequests=0;
 public AccountWriter(Activity a,Callback c){this((Context)a,c);}
 public AccountWriter(Context c,Callback callback){context=c instanceof Activity?c:c.getApplicationContext();activity=c instanceof Activity?(Activity)c:null;this.callback=callback;}
 protected WebView createWebView(){return new WebView(context);}
 private final Runnable idleRelease=()->{if(!busy)destroyWeb();};
 private void releaseLater(){if(web!=null&&!busy)web.setRendererPriorityPolicy(WebView.RENDERER_PRIORITY_WAIVED,true);handler.removeCallbacks(idleRelease);handler.postDelayed(idleRelease,15000);}
 public boolean busy(){return busy;}
 public void releaseIdle(){if(!busy){handler.removeCallbacks(idleRelease);destroyWeb();}}
 private String user(){return context.getSharedPreferences("profile",0).getString("id","");}
 private boolean origin(){return web!=null&&AuthCapture.site(web.getUrl());}
 private void observe(WebResourceRequest r,long epoch){String url=r.getUrl().toString();if(!AuthCapture.api(url))return;String auth=AuthCapture.header(r.getRequestHeaders()),id=AuthCapture.client(url);handler.post(()->{if(closed||epoch!=browserEpoch)return;apiRequests++;if(!auth.isEmpty())observed=auth;if(!id.isEmpty()){client=id;current=true;}executeIfReady();});}
 protected WebViewClient websiteClient(){final long epoch=browserEpoch;return new WebViewClient(){public boolean onRenderProcessGone(WebView w,RenderProcessGoneDetail detail){if(w==web)fail(0,executing?"UNKNOWN_OUTCOME":"RENDERER_GONE",false);return true;}public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return r.isForMainFrame()&&!AuthCapture.site(r.getUrl().toString());}public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){observe(r,epoch);return null;}public void onPageStarted(WebView w,String url,android.graphics.Bitmap icon){if(w!=web||closed)return;ready=false;current=false;pageHost=hostCategory(url);}public void onPageCommitVisible(WebView w,String url){onPageFinished(w,url);}public void onPageFinished(WebView w,String url){if(w!=web||closed)return;pageHost=hostCategory(url);ready=origin();if(!ready)return;w.evaluateJavascript("(window.__sc_hydration||[]).filter(function(x){return x.hydratable==='apiClient';}).map(function(x){return x.data&&x.data.id;})[0]||''",raw->{if(closed||w!=web||epoch!=browserEpoch)return;try{Object id=new JSONTokener(raw).nextValue();if(id instanceof String&&((String)id).matches("[A-Za-z0-9_-]{16,256}")){client=(String)id;current=true;}}catch(Exception ignored){}executeIfReady();});}public void onReceivedHttpError(WebView w,WebResourceRequest r,WebResourceResponse response){if(w==web&&r.isForMainFrame()){pageHttp=response.getStatusCode();fail(pageHttp,"PAGE_HTTP",false);}}public void onReceivedSslError(WebView w,SslErrorHandler h,android.net.http.SslError e){h.cancel();if(w==web)fail(0,"TLS_ERROR",false);}public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(w==web&&r.isForMainFrame()){pageError=e.getErrorCode();fail(0,"PAGE_ERROR",false);}}};}
 public boolean submit(String operation,String id,String list,String name){
  if(busy||closed||!writing.compareAndSet(null,this))return false;handler.removeCallbacks(idleRelease);owner=user();op=operation;track=id;playlist=list;title=name;busy=true;executing=false;deadline=System.currentTimeMillis()+60000;
  try{ensureWeb();executeIfReady();handler.postDelayed(poll,40);return true;}catch(RuntimeException e){fail(0,"WEBVIEW_UNAVAILABLE",false);return true;}
 }
 /** Prepares only a signed-in first-party page; never submits an account mutation. */
 public void warm(){if(closed||busy||writing.get()!=null||user().isEmpty()||Session.get(context).isEmpty())return;try{ensureWeb();releaseLater();}catch(RuntimeException ignored){destroyWeb();}}
 private void ensureWeb(){if(web!=null&&!browserOwner.equals(user()))destroyWeb();if(web!=null)return;browserOwner=user();browserEpoch++;
 web=createWebView();WebSettings settings=web.getSettings();settings.setUserAgentString(AccountBrowserProfile.desktop(settings.getUserAgentString()));settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(true);settings.setBlockNetworkImage(true);web.setRendererPriorityPolicy(WebView.RENDERER_PRIORITY_WAIVED,true);settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);web.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);web.setFocusable(false);web.setFocusableInTouchMode(false);web.setAlpha(0);web.setWebViewClient(websiteClient());if(activity!=null)((ViewGroup)activity.findViewById(android.R.id.content)).addView(web,0,new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));web.loadUrl("https://soundcloud.com/");
 }

 private void executeIfReady(){if(!busy||executing||closed||!ready||!current||!origin())return;if(owner.isEmpty()||!owner.equals(user())){fail(0,"ACCOUNT_MISMATCH",false);return;}web.setRendererPriorityPolicy(WebView.RENDERER_PRIORITY_BOUND,false);String cookie=AuthCapture.cookie(CookieManager.getInstance().getCookie("https://soundcloud.com/"));authUsed=!observed.isEmpty()?observed:!cookie.isEmpty()?cookie:Session.get(context);clientUsed=client;key="_volna_inline_"+UUID.randomUUID().toString().replace("-","");executing=true;web.evaluateJavascript(AccountScript.build(key,authUsed,clientUsed,owner,op,track,playlist,title),null);}
 private final Runnable poll=new Runnable(){public void run(){if(!busy||closed)return;if(!owner.equals(user())){fail(0,"ACCOUNT_MISMATCH",false);return;}if(System.currentTimeMillis()>deadline){fail(0,executing?"UNKNOWN_OUTCOME":ready?"CLIENT_BOOTSTRAP_MISSING":"PAGE_TIMEOUT",false);return;}if(!executing){executeIfReady();handler.postDelayed(this,40);return;}if(!origin()){fail(0,"UNKNOWN_OUTCOME",false);return;}web.evaluateJavascript("JSON.stringify(window["+AccountScript.quote(key)+"]||{})",raw->{if(!busy||closed)return;try{Object value=new JSONTokener(raw).nextValue();JSONObject result=new JSONObject(String.valueOf(value));if(result.length()==0||result.optBoolean("pending")){handler.postDelayed(poll,40);return;}if(!owner.equals(user())){fail(0,"ACCOUNT_MISMATCH",false);return;}if(result.optBoolean("ok")){if(!authUsed.equals(Session.get(context))||!clientUsed.equals(Session.client(context)))Session.put(context,authUsed,clientUsed);java.util.concurrent.CompletableFuture.runAsync(()->CookieManager.getInstance().flush());web.evaluateJavascript("delete window["+AccountScript.quote(key)+"]",null);busy=false;executing=false;releaseWrite();handler.removeCallbacksAndMessages(null);releaseLater();callback.complete(new Intent().putExtra("owner",owner).putExtra("op",op).putExtra("track",track).putExtra("playlist",result.optString("playlist_id")));}else fail(result.optInt("status"),result.optString("reason"),AuthCapture.challenge(result.optString("challenge")));}catch(Exception e){fail(0,"UNKNOWN_OUTCOME",false);}});}};
 private String lastDiagnostic="";
 private static String hostCategory(String url){try{String h=android.net.Uri.parse(url).getHost();return "soundcloud.com".equals(h)||"www.soundcloud.com".equals(h)?"desktop":"m.soundcloud.com".equals(h)?"mobile":AuthCapture.site(url)?"first_party_other":"other";}catch(Exception e){return "unknown";}}
 public String diagnostic(){return lastDiagnostic;}
 private void fail(int status,String reason,boolean verification){if(closed)return;if(!busy){destroyWeb();return;}String v="unknown";try{android.content.pm.PackageInfo p=WebView.getCurrentWebViewPackage();if(p!=null&&p.versionName!=null&&p.versionName.matches("[0-9.]{1,40}"))v=p.versionName;}catch(RuntimeException ignored){}lastDiagnostic="stage="+(executing?"request":"bootstrap")+"; page="+pageHost+"; ready="+ready+"; client="+current+"; apiRequests="+apiRequests+"; pageError="+pageError+"; pageHttp="+pageHttp+"; WebView="+v;busy=false;executing=false;releaseWrite();handler.removeCallbacksAndMessages(null);destroyWeb();callback.failed(status,reason,verification);}
 private void destroyWeb(){browserEpoch++;browserOwner="";ready=false;current=false;observed="";client="";WebView old=web;web=null;if(old!=null){try{old.stopLoading();}catch(RuntimeException ignored){}ViewGroup p=(ViewGroup)old.getParent();if(p!=null)p.removeView(old);try{old.destroy();}catch(RuntimeException ignored){}}}
 public void close(){closed=true;busy=false;releaseWrite();handler.removeCallbacksAndMessages(null);destroyWeb();}
}
